ALTER TABLE public.providers DROP CONSTRAINT providers_category_check;
ALTER TABLE public.providers ADD CONSTRAINT providers_category_check CHECK (category = ANY (ARRAY['pediatrician','dentist','specialist','therapist','childcare','classes and activities','clothing brands','toys','stores','services','other','pediatricians','pediatric dentists','adult dentists','tongue tie and ENT','feeding, sleep and doulas','massage, PT and therapy','preschools and daycares','nannies and sitters','childcare agencies and tips','camps','swim','free and drop-in','shoes and clothes','strollers and car seats','feeding and home gear','travel with kids','toddler tower and furniture','cleaners, handy people and gardeners','utilities, cars and money','real estate and tenants','birthday party venues','dinner delivery and takeout','kid-friendly restaurants','travel and outings','haircuts and styling','photographers','pets','local businesses','kid-friendly restaurants and cafes','toys and books','doctors and specialists','birthday party venues and entertainers','elementary and K-12 schools','mental health','home services and contractors']));
CREATE TABLE public.import_providers (name text, category text, summary text, parent_count int, location text, website text, phone text, address text, booking_url text, positive int, negative int, first_mention date, last_mention date);
CREATE TABLE public.import_mentions (name text, paraphrase text, sentiment text, mentioned_at date, n int);
GRANT ALL ON public.import_providers, public.import_mentions TO service_role;
ALTER TABLE public.import_providers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.import_mentions ENABLE ROW LEVEL SECURITY;